 data=Path(ref["path"]).read_bytes(); assert len(data)==ref["bytes"] and hashlib.sha256(data).hexdigest()==ref["sha256"]
counts=Counter((c["method"],c["stages"][arm]["observed_location"],arm) for c in native["cases"] for arm in ("baseline","fragment")); rows=list(csv.DictReader((d/"representative_locations.tsv").open(),delimiter="\t")); assert len(rows)==11
