 labels={"orthohmm_high_sensitivity":"HS","orthohmm_satellite_v2":"PHY","orthofinder_full":"OF","orthofinder_sequence_only":"OF checkpoint"}; line="| "+" | ".join((labels[row["method"]],row["observed_location"].replace("_"," "),row["baseline_representatives"],row["fragment_representatives"]))+" |"; assert line in sections[1]
