cases={c["case_id"]:c for c in native["cases"]}; a=cases["Case0000"]["stages"]["fragment"]; assert not a["hit_forward"] and not a["hit_reverse"] and a["graph_connected"] and not a["same_seed_group"]; a=cases["Case0026"]["stages"]["fragment"]; assert a["hit_forward"] and a["hit_reverse"] and a["graph_connected"] and a["pair_event"]=="duplication" and not a["predicted"]; a=cases["Case0030"]["stages"]["fragment"]; assert a["same_seed_group"] and not a["predicted"] and a["pair_event"] is None
